function() {
  var el = document.getElementById('__bf_user_data__');
  if (!el) return undefined;
  var out = {};
  if (el.dataset.email) out.email = el.dataset.email;
  if (el.dataset.phone) out.phone_number = el.dataset.phone;
  var addr = {};
  if (el.dataset.firstName) addr.first_name = el.dataset.firstName;
  if (el.dataset.lastName)  addr.last_name  = el.dataset.lastName;
  if (el.dataset.city)      addr.city       = el.dataset.city;
  if (el.dataset.postalCode) addr.postal_code = el.dataset.postalCode;
  if (el.dataset.country)   addr.country    = el.dataset.country;
  if (Object.keys(addr).length) out.address = addr;
  return out;
}
